CREATE TABLE intelligent_controls (
	id INTEGER NOT NULL, 
	topic VARCHAR(100) NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	instruction TEXT NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	sort_order INTEGER, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	updated_at DATETIME, associated_topics JSON, 
	PRIMARY KEY (id)
);
INSERT INTO "intelligent_controls" VALUES(1,'teaching_team','Docente Responsable','La asignatura debe tener al menos un docente, y por lo menos Adjunto, Asociado o Titular, si tiene JTP, o Ayudante de 1º, cumple con la cantidad pero es un Auxiliar y no docente',1,NULL,'2026-02-21 15:41:48','2026-02-21 20:27:53',NULL);
INSERT INTO "intelligent_controls" VALUES(2,'methodology','Precisión en la Propuesta','Los programas analiticos deben establecer con precisión la propuesta metodológica de enseñanza, modalidades/formatos de enseñanza para las actividades académica.',1,NULL,'2026-02-21 17:20:32','2026-02-21 20:30:12',NULL);
INSERT INTO "intelligent_controls" VALUES(3,'methodology','Resultados de Aprendizaje','Especificar todas las actividades formativas necesarias para lograr el RA, colocando el nro. de RA que cada actividad cubre.',0,NULL,'2026-02-21 20:24:49','2026-02-21 22:01:39',NULL);
INSERT INTO "intelligent_controls" VALUES(4,'evaluation','Definición Clara del Sistema de Evaluación','Deben establecer con precisión las actividades, forma de evaluación y los requisitos para acceder al cursado, aprobación y/o promoción de cada asignatura si la hubiera no es obligatorio.',0,NULL,'2026-02-21 20:43:05','2026-02-21 22:01:27','[]');
INSERT INTO "intelligent_controls" VALUES(5,'evaluation','Transparencia y Comunicación de la Evaluación','El método de evaluación debe estar explicitado y comunicado previamente a los estudiantes, asegurando además el acceso a los resultados obtenidos como parte del proceso formativo.',0,NULL,'2026-02-21 20:45:37','2026-02-21 22:01:29','[]');
INSERT INTO "intelligent_controls" VALUES(6,'evaluation','Explicitación de Evaluación Final (Regulares y Libres)','Debe describirse claramente el método de evaluación final de la asignatura, diferenciando las condiciones y modalidades aplicables a estudiantes regulares y libres.',1,NULL,'2026-02-21 20:46:06',NULL,'[]');
