CREATE TABLE proposal_intelligent_control_results (
	id INTEGER NOT NULL, 
	proposal_id INTEGER NOT NULL, 
	control_id INTEGER NOT NULL, 
	passed BOOLEAN NOT NULL, 
	what_failed TEXT, 
	why_failed TEXT, 
	suggestion TEXT, 
	summary TEXT, 
	raw_response JSON, 
	checked_at DATETIME DEFAULT CURRENT_TIMESTAMP, proposed_text TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(proposal_id) REFERENCES proposals (id), 
	FOREIGN KEY(control_id) REFERENCES intelligent_controls (id)
);
INSERT INTO "proposal_intelligent_control_results" VALUES(1,3,1,1,'','','','La asignatura cumple con la regla de control, ya que cuenta con al menos un docente en la categoría de Adjunto, que es considerada una categoría senior. Además, el equipo docente está compuesto por dos Adjuntos y un Ayudante de 1º, lo que asegura que hay suficiente personal docente calificado.','{"pass": true, "what_failed": "", "why_failed": "", "suggestion": "", "proposed_text": "", "summary": "La asignatura cumple con la regla de control, ya que cuenta con al menos un docente en la categor\u00eda de Adjunto, que es considerada una categor\u00eda senior. Adem\u00e1s, el equipo docente est\u00e1 compuesto por dos Adjuntos y un Ayudante de 1\u00ba, lo que asegura que hay suficiente personal docente calificado.", "requested_mode": "delfin", "effective_mode": "ballena", "finish_reason": "stop", "retried_for_length": false, "used_max_tokens": 1250, "model": "gpt-4o", "raw_content": "```json\n{\n  \"pass\": true,\n  \"what_failed\": \"\",\n  \"why_failed\": \"\",\n  \"suggestion\": \"\",\n  \"proposed_text\": \"\",\n  \"summary\": \"La asignatura cumple con la regla de control, ya que cuenta con al menos un docente en la categor\u00eda de Adjunto, que es considerada una categor\u00eda senior. Adem\u00e1s, el equipo docente est\u00e1 compuesto por dos Adjuntos y un Ayudante de 1\u00ba, lo que asegura que hay suficiente personal docente calificado.\"\n}\n```", "associated_topics": []}','2026-02-21 22:27:27.640022','');
INSERT INTO "proposal_intelligent_control_results" VALUES(2,10,1,1,'','','','La asignatura cumple con la regla de control, ya que cuenta con al menos un docente en la categoría de Adjunto, que es considerada una categoría senior. Además, el equipo docente está compuesto por un total de tres miembros, incluyendo un JTP y un Ayudante de 1º, lo cual es adecuado según los criterios establecidos.','{"pass": true, "what_failed": "", "why_failed": "", "suggestion": "", "proposed_text": "", "summary": "La asignatura cumple con la regla de control, ya que cuenta con al menos un docente en la categor\u00eda de Adjunto, que es considerada una categor\u00eda senior. Adem\u00e1s, el equipo docente est\u00e1 compuesto por un total de tres miembros, incluyendo un JTP y un Ayudante de 1\u00ba, lo cual es adecuado seg\u00fan los criterios establecidos.", "requested_mode": "delfin", "effective_mode": "ballena", "finish_reason": "stop", "retried_for_length": false, "used_max_tokens": 1250, "model": "gpt-4o", "raw_content": "```json\n{\n  \"pass\": true,\n  \"what_failed\": \"\",\n  \"why_failed\": \"\",\n  \"suggestion\": \"\",\n  \"proposed_text\": \"\",\n  \"summary\": \"La asignatura cumple con la regla de control, ya que cuenta con al menos un docente en la categor\u00eda de Adjunto, que es considerada una categor\u00eda senior. Adem\u00e1s, el equipo docente est\u00e1 compuesto por un total de tres miembros, incluyendo un JTP y un Ayudante de 1\u00ba, lo cual es adecuado seg\u00fan los criterios establecidos.\"\n}\n```", "associated_topics": []}','2026-02-21 22:28:12.347870','');
INSERT INTO "proposal_intelligent_control_results" VALUES(3,5,1,1,'','','','La asignatura cumple con la regla de control, ya que cuenta con tres docentes en la categoría de ''ADJUNTO'', que es considerada una categoría senior. No se requiere ninguna modificación.','{"pass": true, "what_failed": "", "why_failed": "", "suggestion": "", "proposed_text": "", "summary": "La asignatura cumple con la regla de control, ya que cuenta con tres docentes en la categor\u00eda de ''ADJUNTO'', que es considerada una categor\u00eda senior. No se requiere ninguna modificaci\u00f3n.", "requested_mode": "delfin", "effective_mode": "ballena", "finish_reason": "stop", "retried_for_length": false, "used_max_tokens": 1250, "model": "gpt-4o", "raw_content": "```json\n{\n  \"pass\": true,\n  \"what_failed\": \"\",\n  \"why_failed\": \"\",\n  \"suggestion\": \"\",\n  \"proposed_text\": \"\",\n  \"summary\": \"La asignatura cumple con la regla de control, ya que cuenta con tres docentes en la categor\u00eda de ''ADJUNTO'', que es considerada una categor\u00eda senior. No se requiere ninguna modificaci\u00f3n.\"\n}\n```", "associated_topics": []}','2026-02-21 22:27:56.923454','');
