INSERT INTO "proposals" VALUES(14,'2026 - 1er Cuatrimestre - Ética y Legislación.docx','form_submission',NULL,'Ingeniería Mecatrónica','Ética y Legislación','023-17','1er Cuatrimestre','2026','2',NULL,'EnProceso',NULL,'2026-02-20 23:28:00','[{"id": 25, "name": "VIDAL, CARLOS ANIBAL", "category": "ADJUNTO", "email": "cvid10@yahoo.com.ar", "dedication": "Sin Informar"}, {"id": 26, "name": "G\u00d3MEZ BARRIONUEVO, CLAUDIA BEATRIZ", "category": "AYUDANTE 1\u00ba", "email": "cbgomez@undec.edu.ar", "dedication": "Sin Informar"}]',19,'https://docs.google.com/open?id=1xc9HGixXmrPXXuthwwDwde7suwH0kTosFpfDwiOa7uM','Ética y Legislación','OBLIGATORIA','Cuatrimestral',39,6,45,3,'Ordenamiento Jurídico. Derecho. La ley. Tratados internacionales. Constitución Nacional y Código Civil y Comercial de la Nación. Sujeto (persona humana y persona jurídica), Objeto y Causa de las Relaciones Jurídicas. Actos jurídicos.  Derecho Tributario. Derecho Laboral. Derecho societario. Ética Profesional.','CGS1 - Desempeñarse de manera efectiva en equipos de trabajo - Medio
CGS2 - Comunicarse con efectividad - Medio
CGS3 - Actuar con ética, responsabilidad profesional y compromiso social considerando el impacto económico, social y ambiental de su actividad en el contexto local y global - Alto','','Relación con el perfil profesional esperado:','','[{"id": 1, "description": "\u2026\u2026. - RAN:", "observable_verb": ""}]','[]','[{"id": 1, "number": "", "name": "", "objective": "", "activities": "", "materials": "", "scope": "Aula"}, {"id": 2, "number": "", "name": "", "objective": "", "activities": "", "materials": "", "scope": "Aula"}, {"id": 3, "number": "", "name": "", "objective": "", "activities": "", "materials": "", "scope": "Aula"}]','','','Norma APA):

