INSERT INTO "proposals" VALUES(34,'2026 - 2do Cuatrimestre - Robótica Industrial l.docx','form_submission',NULL,'Ingeniería Mecatrónica','Robótica Industrial l','023-17','2do Cuatrimestre','2026','4',NULL,'Creada',NULL,'2026-02-20 23:37:43','[{"id": 36, "name": "GUIDET CANOVAS, SEBASTIAN OSCAR", "category": "ADJUNTO", "email": "seba.guidet@gmail.com", "dedication": "Exclusivo"}, {"id": 39, "name": "GRAFFIGNA, CARLOS ESTEBAN", "category": "ADJUNTO", "email": "cgraffigna@undec.edu.ar", "dedication": "Sin Informar"}]',39,'https://docs.google.com/open?id=1AGXDv8z50MCiBVHq20IMsMFkB_ihDzFa3I-26nbiaJ8','Robótica Industrial l','OBLIGATORIA','Cuatrimestral',45,45,90,6,'Antecedentes. Definición y clasificación de los robots. Morfología del Robot. Estructura Mecánica de un robot. Descripción Espacial y Transformaciones. Obtención del modelo de Denavit - Hartenberg. Cinemática Directa. Cinemática Inversa. Control Cinemático. Diseño de un controlador y proyecto de un robot. Programación.','CGT1 - Identificar, formular y resolver problemas de ingeniería mecatrónica - Medio
