INSERT INTO "proposals" VALUES(63,'2026 - 2do Cuatrimestre - Programación Orientada a Objetos.docx','form_submission',NULL,'Tecnicatura Universitaria en Desarrollo Web','Programación Orientada a Objetos','013-24','2do Cuatrimestre','2026','1',NULL,'EnProceso',NULL,'2026-02-24 22:14:08','[{"id": 14, "name": "TEJADA, JORGE DAMIAN", "category": "ADJUNTO", "email": "jorgedat@gmail.com", "dedication": "Sin Informar"}]',70,'https://docs.google.com/open?id=1XCtvketQbVbdqeq9Avhc4dNQ7bws1RqxqFZvLTzFFaw','Programación Orientada a Objetos','OBLIGATORIA','Cuatrimestral',60,30,90,6,'Paradigmas fundamentales: estructurado, funcional, lógico. Orientado a objetos.Diseño de clases. Abstracción. Encapsulamiento. Herencia. Polimorfismo. Manejo de errores. Gestión de colecciones.','','','Relación con el perfil profesional esperado:','','[]','[]','[{"id": 1, "number": "", "name": "", "ra_codes": [], "objective": "", "activities": "", "materials": "", "scope": "A DISTANCIA"}, {"id": 2, "number": "", "name": "", "ra_codes": [], "objective": "", "activities": "", "materials": "", "scope": "A DISTANCIA"}, {"id": 3, "number": "", "name": "", "ra_codes": [], "objective": "", "activities": "", "materials": "", "scope": "A DISTANCIA"}]','','','Norma APA):

