CREATE TABLE study_subject_prerequisites (
	id INTEGER NOT NULL, 
	subject_id INTEGER NOT NULL, 
	prerequisite_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(subject_id) REFERENCES study_subjects (id), 
	FOREIGN KEY(prerequisite_id) REFERENCES study_subjects (id)
);
CREATE TABLE study_subjects (
	id INTEGER NOT NULL, 
	term_id INTEGER NOT NULL, 
	code VARCHAR(50), 
	name VARCHAR(255) NOT NULL, 
	character VARCHAR(50), 
	regime VARCHAR(50), 
	theoretical_hours INTEGER, 
	practical_hours INTEGER, 
	total_hours INTEGER, 
	weekly_hours INTEGER, 
	practice_scope TEXT, 
	minimum_content TEXT, 
	generic_competencies TEXT, 
	specific_competencies TEXT, 
	blocks JSON, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(term_id) REFERENCES study_terms (id)
);
INSERT INTO "study_subjects" VALUES(1,1,NULL,'Estructuras de Datos','OBLIGATORIA','Cuatrimestral',30,45,75,5,'Laboratorio de Informatica A','Estructuras de datos: arreglos unidimensionales, arreglos multidimensionales. Manejo de memoria en ejecución. Estructuras de Datos lineales: pilas, colas, listas. Estructuras de Datos no Lineales: grafos y árboles. Almacenamiento en disco: gestión de archivos, acceso secuencial y directo.','CGT2 - Concebir, diseñar y desarrollar proyectos de ingeniería mecatrónica - Bajo
